WITH Subquery1 AS ( WITH inner_cte AS ( SELECT t0.COURSE_NUMBER, t0.SUBJECT_TITLE, t0.NUM_ENROLLED_STUDENTS, t1.TERM_DESCRIPTION, t1.ACADEMIC_YEAR, ROW_NUMBER() OVER (PARTITION BY t1.ACADEMIC_YEAR ORDER BY t0.COURSE_NUMBER) AS window_column FROM LIBRARY_SUBJECT_OFFERED t0 JOIN ACADEMIC_TERMS t1 ON t0.TERM_CODE = t1.TERM_CODE WHERE t0.OFFER_DEPT_NAME = 'Mathematics' AND t0.NUM_ENROLLED_STUDENTS >= 5 ), avg_enrollment AS ( SELECT t1.ACADEMIC_YEAR, AVG(t0.NUM_ENROLLED_STUDENTS) AS avg_students FROM LIBRARY_SUBJECT_OFFERED t0 JOIN ACADEMIC_TERMS t1 ON t0.TERM_CODE = t1.TERM_CODE WHERE t0.OFFER_DEPT_NAME = 'Mathematics' AND t0.NUM_ENROLLED_STUDENTS >= 5 GROUP BY t1.ACADEMIC_YEAR ) SELECT i.COURSE_NUMBER, i.SUBJECT_TITLE, i.NUM_ENROLLED_STUDENTS, i.TERM_DESCRIPTION, i.ACADEMIC_YEAR, i.window_column FROM inner_cte i JOIN avg_enrollment a ON i.ACADEMIC_YEAR = a.ACADEMIC_YEAR WHERE i.NUM_ENROLLED_STUDENTS > a.avg_students ), Subquery2 AS ( WITH inner_cte AS ( SELECT d.DEPARTMENT_NAME, s.SUBJECT_CODE, s.SUBJECT_CODE_DESC, s.COURSE_NUMBER FROM SIS_DEPARTMENT d JOIN SIS_SUBJECT_CODE s ON d.DEPARTMENT_CODE = s.DEPARTMENT_CODE WHERE d.IS_DEGREE_GRANTING = 'Y' ) SELECT inner_cte.DEPARTMENT_NAME, inner_cte.SUBJECT_CODE, inner_cte.SUBJECT_CODE_DESC, inner_cte.COURSE_NUMBER, AVG(ASCII(inner_cte.COURSE_NUMBER)) AS avg_course_number_ascii, VARIANCE(ASCII(inner_cte.COURSE_NUMBER)) AS var_course_number_ascii FROM inner_cte GROUP BY inner_cte.DEPARTMENT_NAME, inner_cte.SUBJECT_CODE, inner_cte.SUBJECT_CODE_DESC, inner_cte.COURSE_NUMBER ) SELECT s1.COURSE_NUMBER, s1.SUBJECT_TITLE, s1.NUM_ENROLLED_STUDENTS, s1.TERM_DESCRIPTION, s1.ACADEMIC_YEAR, s1.window_column, s2.DEPARTMENT_NAME, s2.SUBJECT_CODE, s2.SUBJECT_CODE_DESC, s2.avg_course_number_ascii, s2.var_course_number_ascii FROM Subquery1 s1 JOIN Subquery2 s2 ON s1.COURSE_NUMBER = s2.COURSE_NUMBER ORDER BY s1.ACADEMIC_YEAR, s1.COURSE_NUMBER;